CREATE TABLE specialties (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" character varying(100) NOT NULL,
    CONSTRAINT "PK_specialties" PRIMARY KEY ("Id")
);

CREATE TABLE users (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Login" character varying(50) NOT NULL,
    "PasswordHash" character varying(200) NOT NULL,
    "FullName" character varying(150) NOT NULL,
    "Phone" character varying(20),
    "BirthDate" timestamp without time zone,
    "Role" integer NOT NULL,
    "CreatedAt" timestamp without time zone NOT NULL,
    CONSTRAINT "PK_users" PRIMARY KEY ("Id")
);

CREATE TABLE doctors (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "FullName" character varying(150) NOT NULL,
    "SpecialtyId" integer NOT NULL,
    "Cabinet" character varying(20) NOT NULL,
    "WorkStart" time without time zone NOT NULL,
    "WorkEnd" time without time zone NOT NULL,
    "SlotMinutes" integer NOT NULL,
    "UserId" integer,
    "IsActive" boolean NOT NULL,
    CONSTRAINT "PK_doctors" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_doctors_specialties_SpecialtyId" FOREIGN KEY ("SpecialtyId") REFERENCES specialties ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_doctors_users_UserId" FOREIGN KEY ("UserId") REFERENCES users ("Id") ON DELETE SET NULL
);

CREATE TABLE notifications (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "UserId" integer NOT NULL,
    "Text" character varying(300) NOT NULL,
    "CreatedAt" timestamp without time zone NOT NULL,
    "IsRead" boolean NOT NULL,
    CONSTRAINT "PK_notifications" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_notifications_users_UserId" FOREIGN KEY ("UserId") REFERENCES users ("Id") ON DELETE CASCADE
);

CREATE TABLE appointments (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "DoctorId" integer NOT NULL,
    "PatientId" integer NOT NULL,
    "StartTime" timestamp without time zone NOT NULL,
    "Status" integer NOT NULL,
    "Comment" character varying(300),
    "CreatedAt" timestamp without time zone NOT NULL,
    CONSTRAINT "PK_appointments" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_appointments_doctors_DoctorId" FOREIGN KEY ("DoctorId") REFERENCES doctors ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_appointments_users_PatientId" FOREIGN KEY ("PatientId") REFERENCES users ("Id") ON DELETE CASCADE
);

CREATE UNIQUE INDEX "IX_appointments_DoctorId_StartTime" ON appointments ("DoctorId", "StartTime") WHERE "Status" = 0;

CREATE INDEX "IX_appointments_PatientId" ON appointments ("PatientId");

CREATE INDEX "IX_doctors_SpecialtyId" ON doctors ("SpecialtyId");

CREATE INDEX "IX_doctors_UserId" ON doctors ("UserId");

CREATE INDEX "IX_notifications_UserId" ON notifications ("UserId");

CREATE UNIQUE INDEX "IX_specialties_Name" ON specialties ("Name");

CREATE UNIQUE INDEX "IX_users_Login" ON users ("Login");

